-- AddForeignKey
ALTER TABLE "account" ADD CONSTRAINT "account_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- Emails are stored lower-case, so the exact-match unique index above (needed
-- by Better Auth) is equivalent to the case-insensitive one from M2.
ALTER TABLE "user" ADD CONSTRAINT "user_email_lowercase"
  CHECK ("email" IS NULL OR "email" = lower("email"));

-- =============================================================================
-- PART 2 — Row-Level Security for authentication tables (default deny)
-- =============================================================================
-- These tables hold sessions, password hashes, tokens and rate-limit counters.
-- Only teamhappi_auth (used by Better Auth on the server) gets a policy; every
-- other non-bypass role, including teamhappi_app, sees nothing even if a grant
-- were added by mistake. They have no tenant_id: identity is global.

ALTER TABLE "session" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "session" FORCE ROW LEVEL SECURITY;
CREATE POLICY "auth_only" ON "session" FOR ALL TO teamhappi_auth
  USING (true) WITH CHECK (true);

ALTER TABLE "account" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "account" FORCE ROW LEVEL SECURITY;
CREATE POLICY "auth_only" ON "account" FOR ALL TO teamhappi_auth
  USING (true) WITH CHECK (true);

ALTER TABLE "verification" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "verification" FORCE ROW LEVEL SECURITY;
CREATE POLICY "auth_only" ON "verification" FOR ALL TO teamhappi_auth
  USING (true) WITH CHECK (true);

ALTER TABLE "rate_limit" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "rate_limit" FORCE ROW LEVEL SECURITY;
CREATE POLICY "auth_only" ON "rate_limit" FOR ALL TO teamhappi_auth
  USING (true) WITH CHECK (true);

-- "user" already has RLS (ENABLE + FORCE) with the app's tenant-scoped,
-- read-only "user_visible" policy. Sign-up, sign-in and verification happen
-- before any tenant context exists, so the auth role gets its own policy.
-- It cannot DELETE users (no grant).
CREATE POLICY "auth_identity" ON "user" FOR ALL TO teamhappi_auth
  USING (true) WITH CHECK (true);

-- =============================================================================
-- PART 3 — Least-privilege grants for teamhappi_auth
-- =============================================================================
-- teamhappi_auth owns nothing, cannot create objects, and has NO access to any
-- tenant-owned table, the tenant registry, the permission catalogue, the "app"
-- schema or migration history. teamhappi_app gets nothing here: it never reads
-- sessions, accounts (password hashes), verification tokens or rate limits.

GRANT SELECT, INSERT, UPDATE ON "user" TO teamhappi_auth;
GRANT SELECT, INSERT, UPDATE, DELETE ON "session" TO teamhappi_auth;
GRANT SELECT, INSERT, UPDATE ON "account" TO teamhappi_auth;
GRANT SELECT, INSERT, UPDATE, DELETE ON "verification" TO teamhappi_auth;
-- DELETE lets Better Auth prune expired rate-limit rows (unbounded growth otherwise).
GRANT SELECT, INSERT, UPDATE, DELETE ON "rate_limit" TO teamhappi_auth;
